int main() {
    int n;
    cin >> n;
    vector<string> words(n);
    for (auto &w : words) cin >> w;
    size_t len = words[0].size();
    for (int i = 1; i < n; i++) {
        size_t k = 0;
        while (k < len && k < words[i].size() && words[i][k] == words[0][k]) k++;
        len = k;
    }
    string prefix = words[0].substr(0, len);
    cout << (prefix.empty() ? "NONE" : prefix) << "\n";
    return 0;
}

