solution.cpp:
#include <iostream>
using namespace std;

int n, full;

long long place(int cols, int d1, int d2) {
    if (cols == full) return 1;
    long long total = 0;
    int freeMask = ~(cols | d1 | d2) & full;
    while (freeMask) {
        int bit = freeMask & -freeMask;
        freeMask ^= bit;
        total += place(cols | bit, ((d1 | bit) << 1) & full, (d2 | bit) >> 1);
    }
    return total;
}

int main() {
    cin >> n;
    full = (1 << n) - 1;
    cout << place(0, 0, 0) << "\n";
    return 0;
}

