        for (int j = 0; j < C; j++) {
            if (g[i][j] == '#') continue;
            if (i == 0 && j == 0) { ways[i][j] = 1; continue; }
            long long w = 0;
            if (i > 0) w += ways[i - 1][j];
            if (j > 0) w += ways[i][j - 1];
            ways[i][j] = w % MOD;
        }
